double CPUGeneratorImpl::normal(double mean, double std) {
  if (std == 0) return mean;
  // Box-Muller
  thread_local bool has_cached = false;
  thread_local double cached_val = std::numeric_limits<double>::quiet_NaN();
  double rsqrt;
  double x, y, r;
  if (has_cached) {
    has_cached = false;
    return mean + std * cached_val;
