       y = 2.0 * uniform() - 1.0;
       r = x*x + y*y; }
  while (r >= 1.0 || r == 0.0);
  rsqrt = std::sqrt(-2.0 * std::log(r) / r);
  cached_val = y * rsqrt;
  has_cached = true;
  return mean + std * (x * rsqrt);
}
```

